import { useState } from "react";
import { Link, useNavigate } from "react-router-dom";

export default function Register() {
  const navigate = useNavigate();

  const [user, setUser] = useState({
    name: "",
    email: "",
    password: "",
    role: "Student",
  });

  const [generatedOtp, setGeneratedOtp] = useState("");
  const [enteredOtp, setEnteredOtp] = useState("");
  const [otpVerified, setOtpVerified] = useState(false);

  const handleChange = (e) => {
    setUser({
      ...user,
      [e.target.name]: e.target.value,
    });
  };

  const sendOtp = () => {
    if (!user.email) {
      alert("Please Enter Email First");
      return;
    }

    const otp = Math.floor(
      100000 + Math.random() * 900000
    ).toString();

    setGeneratedOtp(otp);

    alert("OTP Sent Successfully ✅\nOTP : " + otp);
  };

  const verifyOtp = () => {
    if (enteredOtp === generatedOtp) {
      setOtpVerified(true);
      alert("OTP Verified Successfully ✅");
    } else {
      alert("Invalid OTP ❌");
    }
  };

  const handleRegister = (e) => {
    e.preventDefault();

    if (!otpVerified) {
      alert("Please Verify OTP First");
      return;
    }

    const passwordRegex =
      /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]{8,}$/;

    if (!passwordRegex.test(user.password)) {
      alert(
        "Password must contain:\n\n" +
          "• Minimum 8 Characters\n" +
          "• One Uppercase Letter\n" +
          "• One Lowercase Letter\n" +
          "• One Number\n" +
          "• One Special Character"
      );
      return;
    }

    localStorage.setItem("user", JSON.stringify(user));

    alert("Registration Successful ✅");

    navigate("/login");
  };

  return (
    <div
      style={{
        minHeight: "100vh",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        background:
          "linear-gradient(135deg,#0f172a,#1e40af,#7c3aed,#9333ea)",
        padding: "20px",
      }}
    >
      <form
        onSubmit={handleRegister}
        style={{
          width: "480px",
          background: "rgba(255,255,255,0.96)",
          backdropFilter: "blur(12px)",
          padding: "45px",
          borderRadius: "30px",
          boxShadow: "0 25px 70px rgba(0,0,0,0.25)",
          border: "1px solid #e5e7eb",
        }}
      >
        {/* Header */}
        <div
          style={{
            textAlign: "center",
            marginBottom: "30px",
          }}
        >
          <div
            style={{
              width: "75px",
              height: "75px",
              margin: "0 auto 15px",
              borderRadius: "50%",
              background:
                "linear-gradient(135deg,#2563eb,#7c3aed)",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              fontSize: "30px",
              color: "white",
            }}
          >
            👤
          </div>

          <h1
            style={{
              margin: 0,
              color: "#111827",
              fontSize: "32px",
            }}
          >
            Create Account
          </h1>

          <p
            style={{
              color: "#6b7280",
              marginTop: "10px",
            }}
          >
            Register to access RBAC Dashboard
          </p>
        </div>

        {/* Name */}
        <input
          type="text"
          name="name"
          placeholder="Full Name"
          value={user.name}
          onChange={handleChange}
          style={inputStyle}
          required
        />

        {/* Email */}
        <input
          type="email"
          name="email"
          placeholder="Email Address"
          value={user.email}
          onChange={handleChange}
          style={inputStyle}
          required
        />

        {/* Send OTP */}
        <button
          type="button"
          onClick={sendOtp}
          style={blueBtn}
        >
          Send OTP
        </button>

        {/* OTP */}
        <input
          type="text"
          placeholder="Enter OTP"
          value={enteredOtp}
          onChange={(e) =>
            setEnteredOtp(e.target.value)
          }
          style={inputStyle}
        />

        {/* Verify OTP */}
        <button
          type="button"
          onClick={verifyOtp}
          style={orangeBtn}
        >
          Verify OTP
        </button>

        {/* OTP Status */}
        {otpVerified && (
          <div
            style={{
              background: "#ecfdf5",
              color: "#065f46",
              padding: "14px",
              borderRadius: "14px",
              textAlign: "center",
              marginBottom: "15px",
              border: "1px solid #a7f3d0",
              fontWeight: "600",
            }}
          >
            ✅ OTP Verified Successfully
          </div>
        )}

        {/* Password */}
        <input
          type="password"
          name="password"
          placeholder="Password"
          value={user.password}
          onChange={handleChange}
          style={inputStyle}
          required
        />

        <small
          style={{
            color: "#64748b",
            display: "block",
            marginBottom: "15px",
            lineHeight: "1.7",
          }}
        >
          🔐 Password must contain:
          <br />
          • 8+ Characters
          <br />
          • Uppercase Letter
          <br />
          • Lowercase Letter
          <br />
          • Number
          <br />
          • Special Character
        </small>

        {/* Role */}
        <select
          name="role"
          value={user.role}
          onChange={handleChange}
          style={inputStyle}
        >
          <option value="Student">Student</option>
          <option value="Instructor">Instructor</option>
          <option value="Admin">Admin</option>
        </select>

        {/* Register */}
        <button
          type="submit"
          style={greenBtn}
        >
          Register Account
        </button>

        <p
          style={{
            textAlign: "center",
            marginTop: "20px",
            color: "#6b7280",
          }}
        >
          Already have an account?{" "}
          <Link
            to="/login"
            style={{
              color: "#2563eb",
              textDecoration: "none",
              fontWeight: "600",
            }}
          >
            Login
          </Link>
        </p>
      </form>
    </div>
  );
}

const inputStyle = {
  width: "100%",
  padding: "15px 18px",
  marginBottom: "15px",
  border: "1px solid #d1d5db",
  borderRadius: "14px",
  outline: "none",
  fontSize: "15px",
  boxSizing: "border-box",
  background: "#f8fafc",
};

const blueBtn = {
  width: "100%",
  padding: "15px",
  background:
    "linear-gradient(90deg,#2563eb,#3b82f6)",
  color: "white",
  border: "none",
  borderRadius: "14px",
  cursor: "pointer",
  marginBottom: "15px",
  fontWeight: "700",
};

const orangeBtn = {
  width: "100%",
  padding: "15px",
  background:
    "linear-gradient(90deg,#f59e0b,#fb923c)",
  color: "white",
  border: "none",
  borderRadius: "14px",
  cursor: "pointer",
  marginBottom: "15px",
  fontWeight: "700",
};

const greenBtn = {
  width: "100%",
  padding: "16px",
  background:
    "linear-gradient(90deg,#10b981,#059669)",
  color: "white",
  border: "none",
  borderRadius: "14px",
  cursor: "pointer",
  marginTop: "15px",
  fontSize: "16px",
  fontWeight: "700",
};
